  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly grades = GRADES;
  protected readonly people = signal<Person[]>([]);
  protected readonly periods = signal<Period[]>([]);
  protected readonly pools = signal<Pool[]>([]);
  /** Per person id, in cents, their cuts across every pool they are a member of; a pool showing no cut adds nothing. */
  protected readonly personCuts = computed(() => {
    const cuts = new Map<number, number>();
    for (const pool of this.pools()) {
      for (const m of pool.members) {
        if (m.personId !== null && m.cut !== null) cuts.set(m.personId, (cuts.get(m.personId) ?? 0) + cents(m.cut));
      }
    }
    return cuts;
  });
  /** Per person id, their due-total for each period on the sheet, by period id. */
    static final int NAME_MAX = 100;

    /** The most pools a chain of pools, each a member of the one above, may hold. */
    static final int DEPTH_MAX = 3;

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /**
     * A member of a pool as shown: the person (null for a pool), the pool (null for a person), the name, their
     * share, whether they are retired and their cut (null: none).
     */
    public record Member(Long personId, String pool, String name, BigDecimal share, boolean retired, BigDecimal cut) {
    }

    /**
     * A pool as shown: its members in the order they were added, its total share, whether it is balanced and whether
     * it is a crew's.
     */
    public record Shown(String name, List<Member> members, BigDecimal total, boolean balanced, boolean crew) {
    }

    /** The members' cuts for a period: its name and each member's cut (see {@link #key}), those with none left out. */
    public record Then(String period, Map<String, BigDecimal> cuts) {

        /** The member's cut in the pool then; null when the pool or the member was not there, or had none. */
        public BigDecimal cut(String pool, Member member) {
            return cuts.get(key(pool, member));
        }
    }

    /** The key of a member of the named pool: the pool, then the person's id or the member pool's name. */
    public static String key(String pool, Member member) {
        return pool + "\t" + (member.personId() != null ? "person:" + member.personId() : "pool:" + member.pool());
    }

    /** Each member's cut as the pools stand now, by {@link #key}; a member with no cut is left out. */
    @Transactional(readOnly = true)
    public Map<String, BigDecimal> cuts(String sheetId) {
        return cuts(list(sheetId));
    }

    private static Map<String, BigDecimal> cuts(List<Shown> shown) {
        Map<String, BigDecimal> cuts = new HashMap<>();
        shown.forEach(p -> p.members().stream().filter(m -> m.cut() != null)
                .forEach(m -> cuts.putIfAbsent(key(p.name(), m), m.cut())));
        return cuts;
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
        }
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then and its due then (null when none). */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {

        static LogLineView of(ClaimLogLine line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(), money(line.getDue()));
        }
    }

    /**
     * A person with the grade in force on the sheet's today, their own terms in force on it (null: none), their claims, newest first, claimed: the sum of the amounts of the claims (see
     * {@link Dues#claimed}: a hold leaves a claim in it), dueTotal: the sum of the due figures of the claims that count (see
     * {@link Dues#total}, held to the sheet's cap), excess: what the sum is above the cap (0.00 when it is not), and their statements: how many were taken, the last one's due-total (null when
     * there is none or it was n/a) and date (null when there is none), whether they are retired and
     * the date they are retired from (null when not), whether they have any hold and their holds, and how many of the claims
     * that count are overdue and the sum of their due figures, the ids of their patrons, and whether they are
     * active (see {@link Dues#active}), and recentSettled: their recent settled figures (see {@link Dues#recentSettled}), and retiredNow: whether
     * the sheet's today has reached their retirement date (their unbound OPEN and PENDING claims then count in no live total),
     * and aged0to30, aged31to60 and aged61: the due of their OPEN and PENDING claims that count by the claim's age on the
     * sheet's today (see {@link Dues#aged}), and settledTotal and openTotal: the parts of their uncapped due-total
     * from their SETTLED claims and from their OPEN and PENDING claims (see {@link Dues#settledTotal} and
     * {@link Dues#openTotal}; 0.00 with none, never n/a), and their aliases, sorted as names are compared, and clashing: whether their name or an alias is
     * another's on a sheet of the sheet's tree (see {@link PersonService#clashing}), and the sheet they were
     * transferred from (null: none), their past retirements, earliest first, their snapshot lines, oldest first, and
     * their statement lines: one per statement still standing, in the order taken, and the reason of their flag
     * while it is in force on the sheet's today (null otherwise, see {@link Person#flagOn}), and their approver (null: none),
     * and their score (see {@link Dues#score}), a whole number, and their band while both score thresholds are set:
     * HIGH when the score is at or above the high one, MID when at or above the mid one, else LOW (null otherwise).
     */
    public record PersonView(long id, long version, String name, String grade, Integer terms, String contact,
            List<String> tags,
            List<ClaimView> claims,
            String claimed, String dueTotal, String excess, int statementCount, String statedTotal, LocalDate statementDate,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, int overdueCount,
            String overdueTotal, List<Long> patrons, boolean active, String recentSettled, boolean retiredNow,
            String aged0to30, String aged31to60, String aged61, String settledTotal, String openTotal,
            List<String> aliases, boolean clashing, String origin, List<RetirementView> retirements,
            List<SnapshotView> snapshots, List<StatementLineView> statementLines, String flag,
            String approver, String score, String band) {

        /** The person as shown, given the sheet's rates and whether they clash (see {@link PersonService#clashing}). */
        public static PersonView of(Person person, List<Claim> claims, RateTable rates, Statements statements,
                List<Long> patrons, boolean clashing, List<PersonSnapshot> snapshots) {
            return of(person, claims, rates, statements, patrons, clashing, snapshots, Dues.Parts.NONE);
        }

        /** The person as shown, with their parts of the sheet's shared claims (see {@link Dues#parts}). */
        public static PersonView of(Person person, List<Claim> claims, RateTable rates, Statements statements,
                List<Long> patrons, boolean clashing, List<PersonSnapshot> snapshots, Dues.Parts parts) {
            Grades grade = person::gradeOn;
            Holds held = person.leaves();
            BigDecimal claimed = Dues.claimed(claims, held, rates.today());
            List<Claim> overdue = Dues.overdue(claims, grade, rates, held);
            BigDecimal score = Dues.score(grade, claims, rates, held);
            return new PersonView(person.getId(), person.getVersion(), person.getName(),
                    grade.on(rates.today()), person.termsOn(rates.today()), person.getContact(), Tags.list(person.getTags()), claims.stream().map(c -> ClaimView.of(c, grade, rates, held)).toList(), money(claimed),
                    money(Dues.total(grade, claims, rates, held, parts)), money(Dues.excess(grade, claims, rates, held, parts)),
                    statements.count(),
                    money(statements.lastDueTotal()), statements.lastDate(), person.isRetired(),
                    person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    overdue.size(), money(Dues.sum(grade, overdue, rates)),
                    patrons, Dues.active(claims, held, rates.today()),
                    money(Dues.recentSettled(claims, rates.today())), person.retiredOn(rates.today()),
                    money(Dues.aged(grade, claims, rates, held, 0, 30)),
                    money(Dues.aged(grade, claims, rates, held, 31, 60)),
                    money(Dues.aged(grade, claims, rates, held, 61, Long.MAX_VALUE)),
                    money(Dues.settledTotal(grade, claims, rates, held, parts)),
                    money(Dues.openTotal(grade, claims, rates, held, parts)), person.getAliases(), clashing,
                    person.getOrigin(), person.getRetirements().stream()
                            .map(r -> new RetirementView(r.getFromDate(), r.getToDate())).toList(),
                    snapshots.stream().map(s -> new SnapshotView(s.getDay(), s.getDueTotal())).toList(),
                    statements.lines().stream()
                            .map(l -> new StatementLineView(l.date(), l.dueTotal() == null ? "n/a" : money(l.dueTotal())))
                            .toList(),
                    person.flagOn(rates.today()), person.getApprover(),
                    score.toPlainString(), band(score, rates));
        }

        private static String band(BigDecimal score, RateTable rates) {
            Integer mid = rates.settings().scoreMid();
            Integer high = rates.settings().scoreHigh();
            if (mid == null || high == null) {
                return null;
            }
            return score.compareTo(BigDecimal.valueOf(high)) >= 0 ? "HIGH"
                    : score.compareTo(BigDecimal.valueOf(mid)) >= 0 ? "MID" : "LOW";
        }
    }
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.ParentRates;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rate.RateTable;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.DatedSettings;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetSettingRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;

/**
 * The figures of a sheet: each person's claimed, due-total and overdue-total, and the sheet's
 * claimed-total, due-total (a person showing n/a is skipped) and overdue-total, the last two leaving out the
 * single highest and single lowest person's figure when three or more people have one. A change takes the figures before it and, once done,
 * announces the ones it moved. Reads the store directly, within the change's own transaction.
 */
@Service
public class Rollup {

    /**
     * A person's figures as shown: claimed, due-total ({@code n/a} when there is none), and overdue-total
     * (the sum of the due figures of their overdue claims that count).
     */
    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {

        boolean sameFigures(PersonFigures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** A person's score as shown (see {@link Dues#score}), a whole number. */
    public record PersonScore(String name, String score) {
    }

    /** The sheet's claimed-total, due-total and overdue-total as shown. */
    public record Totals(String claimed, String dueTotal, String overdueTotal) {
    }

    /** Everyone's figures by person id, in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, Totals totals) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final ParentRates parents;
    private final ApplicationEventPublisher events;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SheetSettingRepository settings, ParentRates parents, ApplicationEventPublisher events) {
        this.parents = parents;
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.events = events;
    }

    /** Everyone's score now, in list order. */
    public List<PersonScore> scores(String sheetId) {
        RateTable table = table(sheetId);
        Map<Long, List<Claim>> bySheet = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        List<PersonScore> scores = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
            scores.add(new PersonScore(person.getName(),
                    Dues.score(person::gradeOn, theirs, table, person.leaves()).toPlainString()));
        }
        return scores;
    }

    private RateTable table(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? LocalDate.now() : sheet.getToday();
        return new RateTable(rates.findBySheetId(sheetId), today,
                new DatedSettings(settings.findBySheetId(sheetId)), sheet == null ? null : sheet.getPolicyDate(),
                parents.of(sheetId));
    }

    /** The sheet's figures now. */
    public Figures figures(String sheetId) {
        RateTable table = table(sheetId);
        LocalDate today = table.today();
        Map<Long, List<Claim>> bySheet = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, PersonFigures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        List<Person> everyone = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
        Map<Long, Dues.Parts> parts = Person.parts(everyone, bySheet.values().stream().flatMap(List::stream).toList(),
                table);
        for (Person person : everyone) {
            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
            BigDecimal claimed = Dues.claimed(theirs, person.leaves(), today);
            BigDecimal due = Dues.total(person::gradeOn, theirs, table, person.leaves(),
                    parts.getOrDefault(person.getId(), Dues.Parts.NONE));
            BigDecimal overdue = Dues.sum(person::gradeOn, Dues.overdue(theirs, person::gradeOn, table, person.leaves()), table);
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue.setScale(2, RoundingMode.HALF_UP));
            if (due != null) {
                dues.add(due.setScale(2, RoundingMode.HALF_UP));
            }
            figures.put(person.getId(), new PersonFigures(person.getName(), money(claimed),
                    due == null ? "n/a" : money(due), money(overdue)));
        }
        return new Figures(figures, new Totals(money(claimedTotal), money(trimmedSum(dues)), money(trimmedSum(overdues))));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
    }

    /**
     * Announce the figures the change moved since {@code before}: each person whose figures changed (one
     * who did not exist before counting as changed), then the totals when they changed, then each person whose
     * due-total went from at or below the alert threshold (or none) to above it. Nothing when no figure moved.
     */
    public void changed(String sheetId, String user, Figures before) {
        Figures after = figures(sheetId);
        List<PersonFigures> moved = new ArrayList<>();
        after.people().forEach((id, now) -> {
            if (!now.sameFigures(before.people().get(id))) {
                moved.add(now);
            }
        });
        Totals totals = Objects.equals(before.totals(), after.totals()) ? null : after.totals();
        BigDecimal threshold = new DatedSettings(settings.findBySheetId(sheetId)).alertThreshold();
        List<PersonFigures> alerts = new ArrayList<>();
        if (threshold != null) {
            after.people().forEach((id, now) -> {
                PersonFigures was = before.people().get(id);
                if (above(now, threshold) && (was == null || !above(was, threshold))) {
                    alerts.add(now);
                }
            });
        }
        if (!moved.isEmpty() || totals != null) {
            events.publishEvent(new RollupChanged(sheetId, user, moved, totals, alerts));
        }
    }

    /** Whether the person's due-total is above the threshold; never when they have none. */
    private static boolean above(PersonFigures figures, BigDecimal threshold) {
        return !"n/a".equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
    }

    private static String money(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
    }
}

